`timescale 1ns/1ps

module button_event_tb;

    reg clk;
    reg reset_n;
    reg button_n;

    wire event_pulse;
	 
	 // Counts the number of event pulses generated by the DUT.
    integer pulse_count = 0;
	 
// Device Under Test (DUT)
// Tests pushbutton synchronization and event generation.
button_event dut (
    .clk(clk),
    .reset_n(reset_n),
    .button_n(button_n),
    .event_pulse(event_pulse)
);

// Count each event pulse on the falling clock edge.
// This allows the DUT's rising-edge register updates to settle.
always @(negedge clk)
begin
    if (event_pulse)
        pulse_count = pulse_count + 1;
end

// Generate a 50 MHz clock (20 ns period).
initial clk = 1'b0; // initializes the simulated clock to LOW

always #10 clk = ~clk; // waits 10 ns before toggling clock, 
                       //~clk inverts the current value

// Initialize the testbench signals.
initial
begin
    // Start with reset asserted (active-low).
    reset_n = 1'b0;

    // Start with the pushbutton released (active-low).
    button_n = 1'b1;

    // Keep reset active for three clock cycles.
    #60;

    // Release reset to enable normal operation.
    reset_n = 1'b1;
	 
	 // Wait for two additional clock cycles.
	 #40;

	 // Simulate pressing the active-low button.
	 button_n = 1'b0;

	 // Hold the button down for five clock cycles.
	 #100;
	 
	 // TEST 1: Verify that holding the button generates
	// exactly one event pulse.
	if (pulse_count == 1)
	begin
		$display("PASS: Button press generated exactly one pulse.");
	end
	else
	begin
		$display("FAIL: Expected 1 pulse, received %0d.", pulse_count);
	end
	
	// TEST 2: Release the button and press it again.

	// Release the active-low button.
	button_n = 1'b1;

	// Allow the released state to pass through the synchronizer.
	#100;

	// Press the button a second time.
	button_n = 1'b0;

	// Hold the second press for five clock cycles.
	#100;

	// Verify that a second event pulse was generated.
	if (pulse_count == 2)
	begin
		$display("PASS: Second button press generated one additional pulse.");
	end	
	else
	begin
		$display("FAIL: Expected 2 total pulses, received %0d.", pulse_count);
	end
	
	// TEST 3: Verify reset does not generate a button event.

	// Release the button before resetting.
	button_n = 1'b1;
	#100;

	// Assert the active-low reset.
	reset_n = 1'b0;
	
	// Hold reset for three clock cycles.
	#60;

	// Verify no additional events were generated.
	if (pulse_count == 2)
	begin
		$display("PASS: Reset did not generate an additional pulse.");
	end
	else
	begin
		$display("FAIL: Reset generated an unexpected pulse. Count = %0d",
             pulse_count);
	end
	// Prepare for TEST 4: Button held during reset release.
	$display("Preparing reset-release edge case test.");
	
	// TEST 4: Hold the button while releasing reset.

	// Keep reset asserted.
	reset_n = 1'b0;

	// Simulate a button being held down.
	button_n = 1'b0;

	// Allow three clock cycles for reset.
	#60;

	// Release reset while the button remains pressed.
	reset_n = 1'b1;

	// Wait five clock cycles for synchronization.
	#100;

	// Check whether the button generated another pulse.
	if (pulse_count == 3)
	begin
		$display("OBSERVED: Button held during reset release generated a pulse.");
	end
	else if (pulse_count == 2)
	begin
		$display("PASS: Button held during reset release generated no pulse.");
	end
	else
	begin
		$display("FAIL: Unexpected total pulse count = %0d", pulse_count);
		 $fatal(1, "Reset-release test failed.");
	end



	$finish;
end // closes the initial block

endmodule // End of module